fn is_greater(arr: &Vec<i32>, number: i32) -> bool {
    // An empty array means the number is greater than all (non-existent) elements
    if arr.is_empty() {
        return true;
    }
    
    // Check if the number is greater than every element in the array
    for &value in arr {
        if number <= value {
            return false; // Found an element that is not less than the number
        }
    }
    
    true // The number is greater than all elements
}